// [LT] Step 44: the committed image corpus (NFR6.213, NFR6.214, NFR11.204; at least 30 files,
// regenerated by scripts/generate-image-corpus.ts) through the route's sniff and the real sharp
// decoder. Every stored outcome is checked for clean WebP output: no EXIF, XMP or ICC chunk, widths
// within 1,600 px, orientation applied.
import { readdirSync, readFileSync } from 'node:fs';
import sharp from 'sharp';
import { describe, expect, it } from 'vitest';
import { IMAGE_SIGNATURE_BYTES, isCleanWebp, sniffImageFormat } from '../domain/image.ts';
import { configureSharpForWorker, decodeImage } from './image-decode.server.ts';

const DIR = new URL('../test-fixtures/images/', import.meta.url);
type Entry = { file: string; expect: 'stored' | 'imageType' | 'imageUnreadable'; note: string };
const manifest = JSON.parse(readFileSync(new URL('manifest.json', DIR), 'utf8')) as Entry[];
const read = (file: string) => new Uint8Array(readFileSync(new URL(file, DIR)));

/** RIFF chunk names of a WebP buffer. */
function chunks(webp: Uint8Array): string[] {
  const view = new DataView(webp.buffer, webp.byteOffset, webp.byteLength);
  const names: string[] = [];
  let offset = 12;
  while (offset + 8 <= webp.byteLength) {
    names.push(String.fromCharCode(...webp.slice(offset, offset + 4)));
    const size = view.getUint32(offset + 4, true);
    offset += 8 + size + (size % 2);
  }
  return names;
}

async function outcome(bytes: Uint8Array) {
  const format = sniffImageFormat(bytes.slice(0, IMAGE_SIGNATURE_BYTES));
  if (!format) return { reason: 'imageType' as const };
  const result = await decodeImage(bytes, format);
  return result.ok ? { stored: result.value } : { reason: result.reason };
}

configureSharpForWorker();

describe('the image corpus', () => {
  it('has at least 30 files and every file is in the manifest', () => {
    expect(manifest.length).toBeGreaterThanOrEqual(30);
    const files = readdirSync(DIR).filter((f) => f !== 'manifest.json');
    expect(files.sort()).toEqual(manifest.map((m) => m.file).sort());
  });

  it.each(manifest)('$file ($note) → $expect', async (entry) => {
    const result = await outcome(read(entry.file));
    if (entry.expect !== 'stored') {
      expect(result).toEqual({ reason: entry.expect });
      return;
    }
    expect('stored' in result).toBe(true);
    const stored = (
      result as {
        stored: {
          width: number;
          height: number;
          variants: Array<{ width: number; bytes: Uint8Array }>;
        };
      }
    ).stored;
    expect(stored.variants.length).toBeGreaterThanOrEqual(1);
    expect(stored.width).toBeLessThanOrEqual(1600);
    for (const variant of stored.variants) {
      expect(isCleanWebp(variant.bytes)).toBe(true);
      const names = chunks(variant.bytes);
      expect(names).not.toContain('EXIF');
      expect(names).not.toContain('XMP ');
      expect(names).not.toContain('ICCP');
      const meta = await sharp(variant.bytes).metadata();
      expect(meta.format).toBe('webp');
      expect(meta.width).toBeLessThanOrEqual(variant.width);
      expect(meta.exif).toBeUndefined();
      expect(meta.xmp).toBeUndefined();
      expect(meta.icc).toBeUndefined();
    }
  });
});

describe('decodeImage specifics', () => {
  it('applies EXIF orientation 6 (64x32 becomes 32x64) and drops the GPS block', async () => {
    const result = await decodeImage(read('jpeg-exif-gps-orient6.jpg'), 'jpeg');
    expect(result.ok && { width: result.value.width, height: result.value.height }).toEqual({
      width: 32,
      height: 64,
    });
  });

  it('makes all three variants for a wide image and one for a small one, never enlarging', async () => {
    const large = await decodeImage(read('jpeg-large.jpg'), 'jpeg');
    expect(large.ok && large.value.variants.map((v) => v.width)).toEqual([400, 800, 1600]);
    expect(large.ok && large.value.width).toBe(1600);
    const small = await decodeImage(read('jpeg-small.jpg'), 'jpeg');
    expect(small.ok && small.value.variants.map((v) => v.width)).toEqual([400]);
    expect(small.ok && small.value.width).toBe(64);
  });

  it('round-trips the INF-203 self-test JPEG into three variants', async () => {
    const result = await decodeImage(read('selftest.jpg'), 'jpeg');
    expect(result.ok && result.value.variants).toHaveLength(3);
  });

  it('refuses a mismatch between the sniffed and the decoded format with imageType', async () => {
    expect(await decodeImage(read('png-rgb.png'), 'jpeg')).toEqual({
      ok: false,
      reason: 'imageType',
    });
  });
});
